package com.greenocean.backend.trust;
import com.greenocean.backend.common.exception.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional
public class RankingAssurance {
 private final JdbcTemplate db;private final IncidentOperations operations;private final TrustAuthority authority;
 public RankingAssurance(JdbcTemplate db,IncidentOperations operations,TrustAuthority authority){this.db=db;this.operations=operations;this.authority=authority;}
 private void operator(UUID who,UUID sid){operations.require(who,sid,"CLINIC");if(!authority.has(who,"CLINIC_REPUTATION_OPERATOR"))throw new ForbiddenException("Current independent reputation-audit purpose required");}
 public UUID propose(UUID who,UUID sid,UUID policy,String profession,String mode,int interval,String reference){operator(who,sid);IncidentOperations.evidence(reference);if(!Set.of("PSYCHOLOGIST","COUNSELOR","PSYCHIATRIST").contains(profession)||!Set.of("TEXT","AUDIO","VIDEO").contains(mode)||interval<1||interval>90)throw new IllegalArgumentException("Choose an existing cohort/mode and review interval1–90 days");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_ranking_policies WHERE id=? AND approved_at IS NOT NULL AND expires_at>CURRENT_TIMESTAMP)",Boolean.class,policy)))throw new ConflictException("Current independently approved source methodology required");authority.budget(who,"RANKING_AUDIT_PROPOSED",20);return db.queryForObject("INSERT INTO operation_ranking_audits(policy_id,profession,mode,author_id,evidence_reference,review_interval_days) VALUES(?,?,?,?,?,?) RETURNING id",UUID.class,policy,profession,mode,who,reference,interval);}
 public void approve(UUID who,UUID sid,UUID id){operator(who,sid);var r=db.queryForMap("SELECT * FROM operation_ranking_audits WHERE id=? FOR UPDATE",id);if(who.equals(r.get("author_id")))throw new ForbiddenException("Independent methodology/fairness review required");if(r.get("approved_at")!=null||r.get("revoked_at")!=null||!authority.has((UUID)r.get("author_id"),"CLINIC_REPUTATION_OPERATOR"))throw new ConflictException("Current independent unapproved audit required");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_ranking_policies WHERE id=? AND approved_at IS NOT NULL AND expires_at>CURRENT_TIMESTAMP)",Boolean.class,r.get("policy_id"))))throw new ConflictException("Source policy changed or expired");db.update("UPDATE operation_ranking_audits SET reviewer_id=?,approved_at=CURRENT_TIMESTAMP,next_review_at=CURRENT_TIMESTAMP+(review_interval_days*INTERVAL '1 day') WHERE id=?",who,id);authority.audit(who,id,"RANKING_AUDIT_INDEPENDENTLY_APPROVED");}
 public void revoke(UUID who,UUID sid,UUID id){operator(who,sid);if(db.update("UPDATE operation_ranking_audits SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE id=?",id)!=1)throw new NotFoundException("Audit unavailable");authority.audit(who,id,"RANKING_AUDIT_REVOKED");}
 public List<Map<String,Object>> list(UUID who,UUID sid){operator(who,sid);return db.queryForList("SELECT id,policy_id,profession,mode,evidence_reference,review_interval_days,approved_at,next_review_at,revoked_at,author_id=? AS own_proposal FROM operation_ranking_audits ORDER BY created_at DESC LIMIT 50",who);}
 public static void require(JdbcTemplate db,UUID policy,String profession,String mode){if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM operation_ranking_audits a JOIN users u ON u.id=a.reviewer_id JOIN users author ON author.id=a.author_id WHERE a.policy_id=? AND a.profession=? AND a.mode=? AND a.approved_at IS NOT NULL AND a.next_review_at>CURRENT_TIMESTAMP AND a.revoked_at IS NULL AND u.status='ACTIVE' AND u.email_verified AND author.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND r.name='CLINIC_REPUTATION_OPERATOR') AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=author.id AND r.name='CLINIC_REPUTATION_OPERATOR') AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND r.name='TRUST_CLINIC') AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=author.id AND r.name='TRUST_CLINIC'))",Boolean.class,policy,profession,mode)))throw new ForbiddenException("A current independently reviewed cohort-specific fairness audit is required before public ranking or weekly publication");}
}
